from rcb_client import Robot
import numpy as np
r=Robot();s=r.spec();o=r.reset(images=False);lo=np.array(s['qpos']['range'])[:,0];hi=np.array(s['qpos']['range'])[:,1];q=np.array(o['proprio']['joint_pos']);base=np.zeros(19);hip=0.
def norm(x):return np.clip(2*(x-lo)/(hi-lo)-1,-1,1)
for k in range(220):
 gx=o['imu']['gravity'][0]
 if k>=40:
  if gx < -.02: hip=max(-.8,hip-.018)
  elif gx > .02: hip=min(.8,hip+.018)
 t=base.copy();t[2]=hip;t[7]=hip
 tar=q+(t-q)*((k+1)/30) if k<30 else t
 o=r.step('qpos',norm(tar),images=False)
 if (k+1)%5==0:print(o['step'],round(o['imu']['gravity'][0],2),round(o['imu']['gyro'][1],2),round(float(hip),2),round(float(o['proprio']['joint_pos'][2]),2),o['done'])
 if o['done']:break
